pub(crate) fn rt_fill_ramp(b: &crate::port::Bitmap, ch: i32) -> i32 {
    // channel 0 of pixel (x, y) := (37 * (y * w + x)) mod 256; the other
    // channels := 255 - that, so a form reading the wrong one is caught.
    let w: i32 = crate::port::bitmap_w(b);
    let h: i32 = crate::port::bitmap_h(b);
    let mut x: i32 = 0;
    let mut y: i32 = 0;
    let mut v: i32 = 0;
    while y < h {
        x = 0;
        while x < w {
            v = (37 * ((y * w) + x)) % 256;
            crate::port::bitmap_set_u8(b, x, y, 0, v);
            if ch > 1 {
                crate::port::bitmap_set_u8(b, x, y, 1, 255 - v);
            }
            x += 1;
        }
        y += 1;
    }
    return 0;
}
pub(crate) fn rt_same_cells(a: &mut crate::port::Cells, b: &mut crate::port::Cells) -> i32 {
    // 1 when the two hold the same cells.
    let mut i: i32 = 0;
    let mut same: i32 = 1;
    if crate::port::cells_len(a) != crate::port::cells_len(b) {
        same = 0;
    }
    while i < crate::port::cells_len(a) {
        if crate::port::cells_at(a, i) != crate::port::cells_at(b, i) {
            same = 0;
        }
        i += 1;
    }
    return same;
}
