pub(crate) fn rt_ramp_1_9(b: &crate::port::Bitmap) -> i32 {
    let mut y: i32 = 0;
    let mut x: i32 = 0;
    while y < 3 {
        x = 0;
        while x < 3 {
            crate::port::bitmap_set_u8(b, x, y, 0, ((y * 3) + x) + 1);
            x += 1;
        }
        y += 1;
    }
    return 0;
}
